#!/usr/bin/env python3
"""Build only the public SOC3050 preparation files into a static site."""
from pathlib import Path
import argparse, html, json, re, shutil
import markdown
ROOT=Path(__file__).resolve().parents[1]
SOURCE=ROOT/'Midterms/EmbeddedSoftwareDesign/MidtermSamples'
DOCS=['README.md','Study-guide-RU.md','Last-review.md']+[f'{kind}-{v}.md' for v in 'ABC' for kind in ['Sample','Answers']]
CSS='''*{box-sizing:border-box}:root{color-scheme:light dark;--bg:#f3f5f8;--card:#fff;--ink:#17263b;--muted:#536177;--line:#d9e0ea;--accent:#164ba5}body{margin:0;background:var(--bg);color:var(--ink);font:17px/1.7 system-ui,sans-serif}main{max-width:1060px;margin:auto;padding:40px 24px 90px}h1{font-size:clamp(30px,5vw,52px);line-height:1.15;letter-spacing:-.035em}h2{line-height:1.3;margin-top:2em}h3{margin-top:1.7em}p{overflow-wrap:anywhere}a{color:var(--accent);text-underline-offset:3px}.muted,small{color:var(--muted)}nav{display:flex;gap:18px;flex-wrap:wrap;margin-bottom:28px}.eyebrow{font-size:13px;font-weight:750;letter-spacing:.12em;color:var(--accent)}.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:26px;margin:24px 0}.card h2{margin-top:0}.buttons{display:flex;gap:12px;flex-wrap:wrap}.button{display:inline-block;padding:10px 17px;border:1px solid var(--line);border-radius:9px;text-decoration:none;font-weight:650;background:var(--card)}.button.primary{background:var(--accent);color:white;border-color:var(--accent)}table{border-collapse:collapse;width:100%;display:block;overflow-x:auto;margin:22px 0}th,td{border:1px solid var(--line);padding:10px 13px;text-align:left;min-width:85px}th{background:var(--card)}code{font: .9em/1.5 ui-monospace,monospace;background:var(--card);padding:2px 4px;border-radius:4px;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow:auto;border:1px solid var(--line);background:var(--card);padding:17px;border-radius:9px}pre code{padding:0;background:none}blockquote{border-left:3px solid var(--accent);padding-left:20px;margin-left:0}.toc{background:var(--card);border:1px solid var(--line);padding:18px;border-radius:10px}.toc ul{padding-left:22px}article{max-width:900px}a:focus-visible{outline:3px solid #d78d16;outline-offset:4px}h2,h3{scroll-margin-top:20px}footer{border-top:1px solid var(--line);margin-top:50px;padding-top:18px;font-size:14px;color:var(--muted)}@media(prefers-color-scheme:dark){:root{--bg:#111924;--card:#192331;--ink:#e5edf8;--muted:#a4b4cb;--line:#344458;--accent:#88b3ff}.button.primary{color:#111924}}@media(max-width:600px){main{padding:25px 16px 60px}.card{padding:20px}body{font-size:16px}th,td{padding:8px}.buttons{gap:9px}}@media print{nav,.buttons,footer{display:none}body{background:white;color:black}main{padding:0}.toc{display:none}h2,h3{break-after:avoid}tr,pre{break-inside:avoid}a{color:inherit}}'''
def layout(title,body,level=1):
 prefix='../'*level
 return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="SOC3050 ARM midterm preparation: 99 practice questions, worked answers and lessons 00–08."><title>{html.escape(title)} · Exams</title><link rel="stylesheet" href="{prefix}assets/site.css"></head><body><main><nav aria-label="Навигация"><a href="{prefix}index.html">Exams</a><a href="{prefix}embedded/index.html">SOC3050</a><a href="{prefix}embedded/Trainer.html">Пройти тест</a><a href="https://github.com/jamoliddin05/Exams/tree/main/Midterms/EmbeddedSoftwareDesign">GitHub</a></nav>{body}<footer>Самостоятельные тренировочные материалы по ARM midterm Fall 2026. Не официальные экзаменационные вопросы. Вопросы на английском, разборы на русском.</footer></main></body></html>'''
def docname(name):return 'index.html' if name=='README.md' else name[:-3]+'.html'
def build(output):
 output=output.resolve()
 if output==ROOT or ROOT.is_relative_to(output) or output==SOURCE or SOURCE.is_relative_to(output):raise ValueError('Output must not replace the repository or source directory')
 # Keep existing unrelated files safe: build into a fresh sibling and replace only a prior generated site.
 if output.exists() and not (output/'.exam-site-output').exists():raise ValueError('Refusing to overwrite a directory not created by this builder')
 output.mkdir(parents=True,exist_ok=True)
 (output/'.exam-site-output').write_text('Generated by build_exam_site.py\n')
 (output/'assets').mkdir(exist_ok=True);(output/'assets/site.css').write_text(CSS)
 target=output/'embedded';target.mkdir(exist_ok=True)
 for name in DOCS:
  source=(SOURCE/name).read_text()
  # Add a compact TOC to long documents, keeping the original Markdown unchanged.
  if name in ['Study-guide-RU.md','Last-review.md']:source=source.replace('\n## ', '\n[TOC]\n\n## ',1)
  body=markdown.markdown(source,extensions=['tables','fenced_code','toc','sane_lists'])
  def href(m):
   path=m[1]
   if path.startswith(('http:','https:','#','mailto:')):return m[0]
   file,sep,fragment=path.partition('#')
   if file in DOCS:return 'href="'+docname(file)+(sep+fragment if sep else '')+'"'
   if file=='../../../deploy/README.md':return 'href="https://github.com/jamoliddin05/Exams/blob/main/deploy/README.md"'
   return m[0]
  body=re.sub(r'href="([^"]+)"',href,body)
  title=source.splitlines()[0].lstrip('# ')
  body=f'<article>{body}</article><p><a href="{name}">Скачать Markdown</a></p>'
  (target/docname(name)).write_text(layout(title,body))
  shutil.copy2(SOURCE/name,target/name)
 shutil.copy2(SOURCE/'Trainer.html',target/'Trainer.html')
 shutil.copy2(SOURCE/'question-bank.json',target/'question-bank.json')
 root_body='''<header><div class="eyebrow">EXAMS · MIDTERM PREPARATION</div><h1>Подготовка к мидтермам</h1><p class="muted">Материалы из репозитория Exams: решай, проверяй и возвращайся к темам, в которых ошибся.</p></header><section class="card"><div class="eyebrow">SOC3050 · ARM EDITION · FALL 2026</div><h2>Embedded Software Design</h2><p>Три тренировочных варианта: <strong>99 вопросов</strong>, разборы ответов и конспект лекций <strong>00–08</strong>.</p><p>Формат попытки: <strong>33 вопроса · 60 минут · один ответ A–D</strong>. Тренажёр проверяет ответы и показывает ошибки по лекциям.</p><div class="buttons"><a class="button primary" href="embedded/Trainer.html">Пройти тест</a><a class="button" href="embedded/Study-guide-RU.html">Читать конспект</a><a class="button" href="embedded/index.html">Все материалы</a></div></section><section class="card"><h2>Как готовиться</h2><ol><li>Реши вариант A за 60 минут без конспекта и калькулятора.</li><li>Разбери ошибки и открой указанные источники.</li><li>Повтори трудные темы и реши следующий вариант.</li></ol><p><a href="embedded/Last-review.html">Короткое повторение перед экзаменом →</a></p></section>'''
 (output/'index.html').write_text(layout('Подготовка к мидтермам',root_body,0))
 # A release identifies precisely the bank used by the running site.
 import hashlib
 (output/'release.json').write_text(json.dumps({'course':'SOC3050','questions':99,'variants':3,'bank_sha256':hashlib.sha256((SOURCE/'question-bank.json').read_bytes()).hexdigest(),'source_commit':'7906b2fdc7895f9656402033bb5af66f5fd3eee8'},indent=2)+'\n')
 print(f'Built static site: {output}')
if __name__=='__main__':
 parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--output',type=Path,default=ROOT/'dist-exams');args=parser.parse_args();build(args.output)
